'use strict';
let explorerContinent='any',explorerLimit=9;
const normalise=value=>String(value).trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const countryAliases={usa:'US',us:'US','united states of america':'US',america:'US',uk:'GB','united kingdom':'GB',britain:'GB',korea:'KR','south korea':'KR',holland:'NL','the netherlands':'NL','uae':'AE','south-korea':'KR'};
function countryValue(){const value=normalise($('#country-input').value);if(!value)return 'any';return countryAliases[value]||P.countries.find(c=>normalise(c.name)===value||normalise(c.code)===value||c.aliases.some(a=>normalise(a)===value))?.code||'invalid';}
function updateCountrySuggestions(){const region=$('#region').value;const list=P.countries.filter(c=>P.inRegion(c,region)).sort((a,b)=>a.popular-b.popular||a.name.localeCompare(b.name));$('#country-options').innerHTML=list.map(c=>`<option value="${escapeHtml(c.name)}">${escapeHtml(c.continent)}</option>`).join('');}
$('#region').addEventListener('change',()=>{const chosen=P.countries.find(c=>c.code===countryValue());if(chosen&&!P.inRegion(chosen,$('#region').value))$('#country-input').value='';updateCountrySuggestions();});
$('#country-input').addEventListener('change',()=>{const c=P.countries.find(c=>c.code===countryValue());if(c)$('#country-input').value=c.name;});
updateCountrySuggestions();
$('#hero-image').style.backgroundImage='url("images/palawan.jpg")';
function filteredCountries(){const q=normalise($('#explore-search').value);const alias=countryAliases[q];return P.countries.filter(c=>(P.inRegion(c,explorerContinent))&&(!q||(alias?c.code===alias:normalise([c.name,c.official,c.code,...c.capital,...c.aliases,...P.destinations.filter(d=>d.countryCode===c.code).map(d=>d.city)].join(' ')).includes(q)))).sort((a,b)=>$('#country-sort').value==='popular'?(explorerContinent==='Middle East'?P.middleEast.indexOf(a.code)-P.middleEast.indexOf(b.code):a.popular-b.popular)||a.name.localeCompare(b.name):a.name.localeCompare(b.name));}
function renderCountries(){
  const list=filteredCountries(),visible=list.slice(0,explorerLimit);
  $('#country-results-count').textContent=list.length?`Showing ${visible.length} of ${list.length} countries & territories${$('#country-sort').value==='popular'?' · Popular picks first':''}`:'No countries found. Try another spelling or continent.';
  $('#country-grid').innerHTML=visible.map(c=>{
    const d=P.destinations.find(d=>d.countryCode===c.code),photo=d||globalThis.CountryPhotos?.[c.code];
    return `<article class="country-card has-photo"><button class="choose-country" data-country="${c.code}" aria-label="Explore ${escapeHtml(c.name)}"><div class="country-photo">${photo?`<img src="${escapeHtml(photo.image)}" alt="${escapeHtml(photo.caption||d.city+', '+c.name)}" loading="lazy">`:''}<span class="country-photo-label">${escapeHtml(d?.city||c.name)}</span></div><span class="country-card-body"><span><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.continent)}${d?' · Featured pick':''}</small></span><span class="country-arrow" aria-hidden="true">↗</span></span><span class="country-card-note">${d?'Photos, preferences & budget estimate':c.code==='AQ'?'Specialist expedition planning':'Photos, facts & your own budget calculator'}</span></button>${photo?`<p class="country-card-credit">${photoCredit(photo)}</p>`:''}</article>`;
  }).join('');
  if(!list.length)$('#country-grid').innerHTML='<div class="no-country-results"><h3>A different corner of the world?</h3><p>Clear your search or try another continent.</p><button class="outline-button" id="reset-country-search">Show every country</button></div>';
  $('#load-countries').hidden=visible.length>=list.length;$('#load-countries').textContent=`Show ${Math.min(24,list.length-visible.length)} more countries ↓`;
  $$('[data-country]').forEach(b=>b.onclick=()=>chooseCountry(b.dataset.country));
  if($('#reset-country-search'))$('#reset-country-search').onclick=()=>{explorerContinent='any';$('#explore-search').value='';explorerLimit=9;updateContinentTabs();renderCountries();};
}
function chooseCountry(code){
  const c=P.countries.find(c=>c.code===code);if(!c)throw Error('Choose a country from the directory.');
  $('#country-input').value=c.name;$('#region').value=c.continent;updateCountrySuggestions();
  try{const settings=P.validate(readForm());findTrips(settings);$('#country-input-hint').textContent=`${c.name} selected. Clear this field to compare countries again.`;return snapshot();}catch(error){$('#results').hidden=true;$('.workspace').hidden=false;$('.intro').hidden=false;showStep(0);showError(error.message);$('#planner').scrollIntoView({behavior:'instant',block:'start'});throw error;}
}
function updateContinentTabs(){$$('[data-continent]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.continent===explorerContinent)));}
$$('[data-continent]').forEach(b=>b.onclick=()=>{explorerContinent=b.dataset.continent;explorerLimit=12;updateContinentTabs();renderCountries();});
$('#explore-search').addEventListener('input',()=>{explorerLimit=24;renderCountries();});
$('#country-sort').addEventListener('change',()=>{explorerLimit=12;renderCountries();});
$('#load-countries').onclick=()=>{explorerLimit+=24;renderCountries();};
function renderUnpricedCountry(d){
  const c=d.countryRecord,isAntarctica=c.code==='AQ',links=P.links(d,trip),photo=destinationPhoto(d);
  $('#results-title').textContent=isAntarctica?'A different kind of adventure.':`Let’s explore ${c.name}.`;
  $('#results-content').innerHTML=`${detailToolbar()}<div class="match-notice">${isAntarctica?'Antarctica is a continent for specialist expedition travel. Hotel and flight estimates do not apply.':'You can explore this country now. A detailed trip estimate is not available yet, so budget fit has not been assessed.'}</div><div class="country-overview-grid"><div class="country-overview">${photo?`<img class="country-detail-photo" src="${escapeHtml(photo.image)}" alt="${escapeHtml(photo.caption||c.name)}"><p class="photo-credit">${photoCredit(photo)}</p>`:''}<p class="eyebrow">${escapeHtml(c.continent.toUpperCase())}</p><span class="overview-code" aria-hidden="true">${c.code}</span><h2>${escapeHtml(c.name)}</h2><p>${escapeHtml(c.official)}</p><dl><div><dt>${c.capital.length>1?'Capitals':'Capital'}</dt><dd>${escapeHtml(c.capital.join(', ')||'Not applicable')}</dd></div><div><dt>Region</dt><dd>${escapeHtml(c.subregion||c.continent)}</dd></div><div><dt>Currency</dt><dd>${escapeHtml(c.currencies.map(v=>v.name+' ('+v.code+')').join(', ')||'Not listed')}</dd></div><div><dt>Languages listed</dt><dd>${escapeHtml(c.languages.join(', ')||'Not listed')}</dd></div></dl></div><div class="budget-card unpriced-card">${renderBudgetCalculator(d)}${renderArrivalAirport(d)}<p class="calc-provider-note">${isAntarctica?'Use the expedition operator’s package quote and enter 0 for meals or transport already included.':'Check current prices with the providers and enter them above. Choose an arrival airport or nearby gateway before searching.'}</p>${isAntarctica?'<a class="primary-button" href="https://iaato.org/" target="_blank" rel="noopener noreferrer">Explore Antarctic expeditions ↗</a>':`<div class="booking-buttons"><a class="primary-button" href="${escapeHtml(links.hotels)}" target="_blank" rel="noopener noreferrer">Find hotels ↗</a>${flightPriceLink(d,trip)}</div><p class="booking-caption">Opens Booking.com and Google Flights. Availability is not confirmed. Verify your destination, arrival dates, guests, and total with the provider.</p>`}<button class="browse-all-link text-button" id="browse-another-country">Browse another country ↓</button></div></div>`;
  bindDetailActions();
  $('#browse-another-country').onclick=()=>$('#country-explorer').scrollIntoView({behavior:'smooth',block:'start'});
  $('#announcements').textContent=`${c.name} selected. Your personal trip calculator is ready.`;$('#results-title').focus({preventScroll:true});$('#results').scrollIntoView({behavior:'instant',block:'start'});
}
renderCountries();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'select_trip_country',title:'Explore any country',description:'Select any country or territory by code and update the displayed trip. Featured countries have illustrative estimates; every country has a personal budget calculator, facts, and provider searches. No reservation or payment.',inputSchema:{type:'object',properties:{countryCode:{type:'string',enum:P.countries.map(c=>c.code)}},required:['countryCode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>chooseCountry(input.countryCode)},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
